    if(it.k==='world'){camera.rotation.y=cr+it.yaw;camera.updateMatrixWorld();}
    if(it.k==='zpool'){try{if(!ghost.children.length)buildGhost('wall');sv.push([ghost,ghost.visible]);ghost.visible=true;ghost.position.copy(player.pos);}catch(e){}for(const z of zombies)if(z&&z.g&&!z.g.visible){sv.push([z.g,z.g.visible]);z.g.visible=true;z.g.traverse(o=>{if(o.isMesh){sv.push([o,null,o.frustumCulled]);o.frustumCulled=false;}});}}
