// ---- Europe/Rome calendar helpers ----
function day432(ms){try{const o=romeParts(ms==null?Date.now():ms);return o.year+'-'+o.month+'-'+o.day;}catch(e){const d=new Date(ms==null?Date.now():ms);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}}
function dayDiff432(a,b){const p=s=>{const [y,m,d]=s.split('-').map(Number);return Date.UTC(y,m-1,d)/864e5;};return Math.round(p(b)-p(a));}
function wkday432(){try{return romeParts(Date.now()).weekday;}catch(e){return ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][new Date().getDay()];}}
