function wk432On(){const f=window.__wk432force;if(f===true||f===false)return f;const q=/[?&]wk432=([01])/.exec(location.search);if(q)return q[1]==='1';return !!WEEKEND432.on&&WEEKEND432.days.includes(wkday432());}
